import React, { useState, useEffect } from 'react';

// Helper function to extract first name from full name
const getFirstName = (fullName) => {
  return fullName.split(' ')[0];
};

// Mock data generator - creates 6 active agents and 6 empty desks
const generateMockAgents = () => {
  const hebrewFirstNames = ['מאיר', 'אליה', 'יונתן', 'יעקב', 'שמעון', 'עדן'];
  const lastNames = ['כהן', 'לוי', 'ישראלי', 'דוד', 'בן דוד', 'אברהם', 'מוזס', 'שמעוני', 'פרץ', 'גולדברג'];
  const statuses = ['READY', 'NOT_READY'];

  const agents = [];

  // Generate 6 active agents (desks 1-6)
  for (let i = 0; i < 6; i++) {
    const firstName = hebrewFirstNames[i % hebrewFirstNames.length];
    const lastName = lastNames[Math.floor(Math.random() * lastNames.length)];
    const status = statuses[Math.floor(Math.random() * statuses.length)];

    agents.push({
      id: i + 1,
      fullName: `${firstName} ${lastName}`,
      status: status,
      isEmpty: false
    });
  }

  // Generate 6 empty desks (desks 7-12)
  for (let i = 6; i < 12; i++) {
    agents.push({
      id: i + 1,
      fullName: 'עמדה ריקה',
      status: 'EMPTY',
      isEmpty: true
    });
  }

  return agents;
};

const FinesseDashboard = () => {
  const [agents, setAgents] = useState([]);
  const [currentHour, setCurrentHour] = useState(new Date().getHours());

  // Initialize mock data
  useEffect(() => {
    setAgents(generateMockAgents());
  }, []);

  // Dynamic Day/Night Mode Effect
  // This hook checks the current hour and applies/removes the 'dark' class
  // Day mode: 06:00 - 18:00 (hours 6-17)
  // Night mode: 18:00 - 06:00 (hours 18-23 and 0-5)
  useEffect(() => {
    const hour = new Date().getHours();
    setCurrentHour(hour);

    // Apply dark class for night mode, remove for day mode
    if (hour >= 18 || hour < 6) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, []);

  const getStatusColor = (status, isEmpty) => {
    if (isEmpty) {
      return 'bg-gray-300 border-gray-400 dark:bg-gray-800 dark:border-gray-700';
    }
    return status === 'READY' 
      ? 'bg-green-500 border-green-400 shadow-green-500/20 dark:bg-green-600 dark:border-green-500' 
      : 'bg-red-500 border-red-400 shadow-red-500/20 dark:bg-red-600 dark:border-red-500';
  };

  const getStatusIndicator = (status, isEmpty) => {
    if (isEmpty) {
      return (
        <div className="w-3 h-3 rounded-full bg-gray-400 dark:bg-gray-600"></div>
      );
    }
    return (
      <div className={`w-3 h-3 rounded-full ${status === 'READY' ? 'bg-green-300 dark:bg-green-400' : 'bg-red-300 dark:bg-red-400'} animate-pulse`}></div>
    );
  };

  // Mock metrics data - in real app, this would come from API
  const totalDailyCalls = 342;
  const callsWaiting = 5;

  return (
    <div className={`min-h-screen bg-gray-100 dark:bg-slate-900 text-gray-800 dark:text-gray-100 p-8 transition-colors duration-300`}>
      <div className="max-w-7xl mx-auto">
        {/* Header with Metrics */}
        <div className="text-center mb-8">
          <h1 className="text-4xl font-bold mb-2 text-blue-600 dark:text-blue-400">Call Center Dashboard</h1>
          <p className="text-gray-600 dark:text-gray-400 mb-4">Real-time Agent Status Monitor</p>

          {/* Global Metrics Bar */}
          <div className="flex justify-center space-x-8 mb-6">
            <div className="bg-white dark:bg-gray-800 rounded-lg px-6 py-3 shadow-md border border-gray-200 dark:border-gray-700">
              <div className="text-2xl font-bold text-blue-600 dark:text-blue-400">{totalDailyCalls}</div>
              <div className="text-sm text-gray-600 dark:text-gray-400">Total Daily Calls</div>
            </div>
            <div className="bg-white dark:bg-gray-800 rounded-lg px-6 py-3 shadow-md border border-gray-200 dark:border-gray-700">
              <div className={`text-2xl font-bold ${callsWaiting > 0 ? 'text-orange-500 animate-pulse' : 'text-green-600 dark:text-green-400'}`}>
                {callsWaiting}
              </div>
              <div className="text-sm text-gray-600 dark:text-gray-400">Calls Waiting</div>
            </div>
          </div>
        </div>

        {/* 
          Physical Room Layout Container
          Fixed aspect ratio: 1030x380 pixels (2.7:1 proportion)
          CSS Grid Layout with 3 vertical zones:
          - Zone 1 (Left): 400px - Contains internal desk arrays
          - Zone 2 (Center): 230px - Central aisle with main screen
          - Zone 3 (Right): 400px - Future expansion space
        */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-2xl border border-gray-200 dark:border-gray-700 overflow-hidden">
          <div 
            className="grid grid-cols-[400px_230px_400px] h-[380px] relative"
            style={{ aspectRatio: '1030/380' }}
          >

            {/* 
              Zone 1: Left Side (400px wide)
              Contains 12 internal rectangular desks arranged in two sub-arrays
              - Top Sub-Array: 2 columns × 3 rows (6 desks)
              - Bottom Sub-Array: 3 columns × 2 rows (6 desks)
            */}
            <div className="bg-gray-50 dark:bg-gray-900 p-4 border-r border-gray-200 dark:border-gray-700">
              {/* Top Sub-Array: 2x3 grid (desks 1-6) */}
              <div className="grid grid-cols-2 gap-2 h-[45%] mb-2">
                {agents.slice(0, 6).map((agent) => (
                  <div
                    key={agent.id}
                    className={`relative p-3 rounded-lg border-2 ${getStatusColor(agent.status, agent.isEmpty)} 
                               transform transition-all duration-200 hover:scale-105 hover:shadow-lg
                               flex flex-col items-center justify-center text-center`}
                  >
                    <div className="flex flex-col items-center space-y-1">
                      <div className={`text-lg font-bold ${agent.isEmpty ? 'text-gray-500 dark:text-gray-600' : 'text-white'}`}>
                        {getFirstName(agent.fullName)}
                      </div>
                      {getStatusIndicator(agent.status, agent.isEmpty)}
                    </div>
                    <div className="text-xs text-gray-600 dark:text-gray-400 mt-1">
                      Desk {agent.id}
                    </div>
                  </div>
                ))}
              </div>

              {/* Bottom Sub-Array: 3x2 grid (desks 7-12) */}
              <div className="grid grid-cols-3 gap-2 h-[45%]">
                {agents.slice(6, 12).map((agent) => (
                  <div
                    key={agent.id}
                    className={`relative p-3 rounded-lg border-2 ${getStatusColor(agent.status, agent.isEmpty)} 
                               transform transition-all duration-200 hover:scale-105 hover:shadow-lg
                               flex flex-col items-center justify-center text-center`}
                  >
                    <div className="flex flex-col items-center space-y-1">
                      <div className={`text-lg font-bold ${agent.isEmpty ? 'text-gray-500 dark:text-gray-600' : 'text-white'}`}>
                        {getFirstName(agent.fullName)}
                      </div>
                      {getStatusIndicator(agent.status, agent.isEmpty)}
                    </div>
                    <div className="text-xs text-gray-600 dark:text-gray-400 mt-1">
                      Desk {agent.id}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* 
              Zone 2: Central Aisle (230px wide)
              Contains the main screen positioned in upper right quadrant
              and central aisle indicator
            */}
            <div className="bg-gray-100 dark:bg-gray-800 relative border-r border-gray-200 dark:border-gray-700">
              {/* Main Screen - positioned in upper right quadrant */}
              <div className="absolute top-4 right-4 w-32 h-20 bg-gray-700 dark:bg-gray-900 rounded-lg shadow-inner border border-gray-600 dark:border-gray-500 flex flex-col items-center justify-center">
                <div className="text-center">
                  <div className="text-xs text-gray-400 dark:text-gray-500 mb-1">MAIN SCREEN</div>
                  <div className="text-xl font-bold text-blue-400 dark:text-blue-300">
                    {agents.filter(a => !a.isEmpty && a.status === 'READY').length} / {agents.filter(a => !a.isEmpty).length}
                  </div>
                  <div className="text-xs text-gray-400 dark:text-gray-500">Ready</div>
                </div>
              </div>

              {/* Central Aisle Label */}
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="text-gray-500 dark:text-gray-600 text-sm font-semibold tracking-wider transform -rotate-90">
                  CENTRAL AISLE
                </div>
              </div>
            </div>

            {/* 
              Zone 3: Right Side (400px wide)
              Reserved for future expansion
            */}
            <div className="bg-gray-50 dark:bg-gray-900 p-4">
              <div className="h-full flex items-center justify-center">
                <div className="text-center">
                  <div className="text-gray-400 dark:text-gray-600 text-lg font-semibold mb-2">
                    FUTURE EXPANSION
                  </div>
                  <div className="text-gray-500 dark:text-gray-700 text-sm">
                    Additional workstations
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Legend and Stats */}
        <div className="mt-6 bg-white dark:bg-gray-800 rounded-lg p-4 shadow-md border border-gray-200 dark:border-gray-700">
          <div className="flex justify-between items-center">
            {/* Legend */}
            <div className="flex space-x-6">
              <div className="flex items-center space-x-2">
                <div className="w-4 h-4 bg-green-500 dark:bg-green-600 rounded"></div>
                <span className="text-sm text-gray-600 dark:text-gray-400">Ready</span>
              </div>
              <div className="flex items-center space-x-2">
                <div className="w-4 h-4 bg-red-500 dark:bg-red-600 rounded"></div>
                <span className="text-sm text-gray-600 dark:text-gray-400">Not Ready</span>
              </div>
              <div className="flex items-center space-x-2">
                <div className="w-4 h-4 bg-gray-300 dark:bg-gray-800 rounded"></div>
                <span className="text-sm text-gray-600 dark:text-gray-400">Empty</span>
              </div>
            </div>

            {/* Current Mode Indicator */}
            <div className="text-sm text-gray-500 dark:text-gray-400">
              {currentHour >= 18 || currentHour < 6 ? '🌙 Night Mode' : '☀️ Day Mode'} ({currentHour}:00)
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FinesseDashboard;
